import{_ as r,o as a,c as i,a2 as o}from"./chunks/framework.Buc7gXeZ.js";const c=JSON.parse('{"title":"词条编辑与合并规范","description":"MetaFusion 社区词条编辑原则、命名规范、消歧与实体合并准则。","frontmatter":{"title":"词条编辑与合并规范","description":"MetaFusion 社区词条编辑原则、命名规范、消歧与实体合并准则。","order":20,"group":"guide"},"headers":[],"relativePath":"editing-guide.md","filePath":"editing-guide.md"}'),e={name:"editing-guide.md"};function n(l,t,s,d,h,g){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="词条编辑与合并规范" tabindex="-1">词条编辑与合并规范 <a class="header-anchor" href="#词条编辑与合并规范" aria-label="Permalink to &quot;词条编辑与合并规范&quot;">​</a></h1><p>MetaFusion 是一个由社区共同维护的开放元数据资源平台。所有注册用户均可参与词条创建、元数据修正与实体合并。为了保障全站元数据的准确性、一致性与可检索性，请在编辑时遵循以下规范。</p><hr><h2 id="_1-基本编辑原则" tabindex="-1">1. 基本编辑原则 <a class="header-anchor" href="#_1-基本编辑原则" aria-label="Permalink to &quot;1. 基本编辑原则&quot;">​</a></h2><ul><li><strong>客观考据</strong>：词条信息应基于官方网站、发行物包装、权威数据库（如 MusicBrainz、VGMdb、Bangumi、IMDb 等）客观录入，避免主观评测或个人感想。</li><li><strong>信息完整</strong>：在创建或编辑作品时，尽量完善原名、外文名、发行日期、分类标签、制作团队及封面图片。</li><li><strong>改动说明（Edit Note）</strong>：每次提交修改时，请简要说明修改原因或信息来源，便于社区审核与历史追溯。</li><li><strong>来源引用（Source URLs）</strong>：附带可验证的参考链接（如官网介绍页、权威条目页），有助于提升词条可信度。</li></ul><hr><h2 id="_2-词条命名与多语言规范" tabindex="-1">2. 词条命名与多语言规范 <a class="header-anchor" href="#_2-词条命名与多语言规范" aria-label="Permalink to &quot;2. 词条命名与多语言规范&quot;">​</a></h2><h3 id="作品与发行版命名" tabindex="-1">作品与发行版命名 <a class="header-anchor" href="#作品与发行版命名" aria-label="Permalink to &quot;作品与发行版命名&quot;">​</a></h3><ul><li><strong>首选原名</strong>：优先使用作品官方原始发行语言的名称（如日文原名、英文原名）。</li><li><strong>多语言别名</strong>：在“多语言翻译/别名”中补充中文译名、英文译名及拼音/罗马字，以便全球用户和不同输入习惯的读者检索。</li><li><strong>标点符号</strong>：使用半角或全角标点应与官方原始排版保持一致；副标题推荐使用空格或冒号分隔。</li></ul><h3 id="创作者命名" tabindex="-1">创作者命名 <a class="header-anchor" href="#创作者命名" aria-label="Permalink to &quot;创作者命名&quot;">​</a></h3><ul><li><strong>个人与团体</strong>：优先使用创作者最广为人知的官方艺名/常用名；对于一人多艺名的情况，建议建立主实体并在别名中补充其他艺名。</li><li><strong>多重身份</strong>：创作者实体独立于具体作品，通过作品中的“身份角色”（如监督、声优、作词、作曲）建立关联，切勿按作品重复创建同一人物。</li></ul><hr><h2 id="_3-frbr-实体层级拆分准则" tabindex="-1">3. FRBR 实体层级拆分准则 <a class="header-anchor" href="#_3-frbr-实体层级拆分准则" aria-label="Permalink to &quot;3. FRBR 实体层级拆分准则&quot;">​</a></h2><p>录入多媒体资源时，请按照平台的五层 LRM 架构清晰拆分：</p><table tabindex="0"><thead><tr><th>实体层级</th><th>对应内容</th><th>举例</th></tr></thead><tbody><tr><td><strong>作品 (Work)</strong></td><td>抽象创作概念与核心母题</td><td>《攻壳机动队》剧场版、《残酷天使的行动纲领》</td></tr><tr><td><strong>内容单元 (ContentUnit)</strong></td><td>同作品内的稳定目录节点</td><td>第 1 话、第三章、游戏路线</td></tr><tr><td><strong>表达 (Expression)</strong></td><td>某一 Work 的具体创作表达，可关联该作品的 ContentUnit</td><td>原版立体声母带、导演剪辑版正片、中文译本、2020 重制版</td></tr><tr><td><strong>发行 (Release)</strong></td><td>商业发售或发布的具体出版包，<code>subjects</code> 可关联多个 Work</td><td>2003 发行的初回限定版 CD (Catalog No: KICA-1234)</td></tr><tr><td><strong>载体与曲目 (Medium &amp; Track)</strong></td><td>物理/数字介质与曲目编号</td><td>Disc 1 (CD) 中的 Track 01、单行本第 1 卷</td></tr></tbody></table><hr><h2 id="_4-外部权威标识关联" tabindex="-1">4. 外部权威标识关联 <a class="header-anchor" href="#_4-外部权威标识关联" aria-label="Permalink to &quot;4. 外部权威标识关联&quot;">​</a></h2><p>为打破数据孤岛并支持自动化识别，平台支持为实体关联外部权威 ID。建议录入时补充以下标识：</p><ul><li><strong>音乐类</strong>：MusicBrainz ID, VGMdb ID, ISRC</li><li><strong>动画/影视类</strong>：Bangumi ID, AniList ID, IMDb ID, TMDb ID</li><li><strong>文学/出版物</strong>：ISBN, VNDB ID (视觉小说), 豆瓣读书 ID</li></ul><hr><h2 id="_5-实体消歧与重复合并准则" tabindex="-1">5. 实体消歧与重复合并准则 <a class="header-anchor" href="#_5-实体消歧与重复合并准则" aria-label="Permalink to &quot;5. 实体消歧与重复合并准则&quot;">​</a></h2><h3 id="何时需要合并" tabindex="-1">何时需要合并 <a class="header-anchor" href="#何时需要合并" aria-label="Permalink to &quot;何时需要合并&quot;">​</a></h3><p>当发现平台中存在同一实体被重复创建时（例如因译名不同创建了两个《EVA》条目）：</p><ol><li><strong>确认同一性</strong>：比对官方编号、创作者与发行日期，确认确实指向同一个物理或数字作品。</li><li><strong>选择保留主体</strong>：选择创建时间较早、元数据较完善或关联资源较多的实体作为目标实体（Target）。</li><li><strong>发起合并</strong>：在实体管理工具中提交合并申请，填写合并理由（如“与官方条目重复，合并至早期完整条目”）。</li></ol><h3 id="合并后的数据处理" tabindex="-1">合并后的数据处理 <a class="header-anchor" href="#合并后的数据处理" aria-label="Permalink to &quot;合并后的数据处理&quot;">​</a></h3><ul><li>系统会自动将原实体的关联关系、曲目、修订历史迁移至目标实体。</li><li>原实体将标记为“已合并”状态，并自动重定向至目标实体，确保旧链接不失效。</li></ul><hr><h2 id="_6-违规与争议处理" tabindex="-1">6. 违规与争议处理 <a class="header-anchor" href="#_6-违规与争议处理" aria-label="Permalink to &quot;6. 违规与争议处理&quot;">​</a></h2><ul><li><strong>恶意破坏与灌水</strong>：严禁提交虚假信息、恶意清空元数据或批量灌水垃圾内容。违规账号将被限制编辑权限。</li><li><strong>观点与分类争议</strong>：对于作品题材、分类或标签存在争议的情况，可在社区“文献与考据讨论”板块发帖交流，由社区共同讨论或站务协助判定。</li><li><strong>历史回退</strong>：如遇误操作，可通过实体详情的“修订历史 (Revision History)”查看历史差异并申请恢复至指定版本。</li></ul>',29)])])}const b=r(e,[["render",n]]);export{c as __pageData,b as default};
